?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo htmlspecialchars($browserTitle, ENT_QUOTES, 'UTF-8'); ?></title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#20242a;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}.wrap{width:92%;max-width:420px;margin:32px auto;padding:26px 22px 30px;background:#fff;border-radius:8px;box-shadow:0 6px 24px rgba(0,0,0,.08);text-align:center}h1{margin:0 0 12px;font-size:22px;font-weight:600}.icon{width:20px;height:20px;margin-right:6px;vertical-align:-3px}.amount{margin-bottom:14px;color:#1677ff;font-size:30px;font-weight:700}.qr-box{position:relative;width:250px;height:250px;margin:16px auto;padding:10px;border:1px solid #e7eaee;background:#fff}#qrcode{width:230px;height:230px;display:flex;align-items:center;justify-content:center;overflow:hidden}#qrcode img,#qrcode canvas{max-width:230px;max-height:230px}.error{margin:26px 0;color:#d93025;line-height:1.7}.countdown{margin:12px 0;color:#e64340;font-size:16px}.meta{margin:8px 0 14px;color:#8a919b;font-size:13px;line-height:1.8}.hint{color:#8a919b;font-size:14px;line-height:1.7}</style></head><body><main class="wrap"><h1><img class="icon" src="<?php echo htmlspecialchars($paymentIcon, ENT_QUOTES, 'UTF-8'); ?>" alt=""><?php echo htmlspecialchars($title, ENT_QUOTES, 'UTF-8'); ?></h1><div class="amount">￥<?php echo htmlspecialchars((string)$order['realmoney'], ENT_QUOTES, 'UTF-8'); ?></div><?php if ($error_msg !== ''): ?><div class="error"><?php echo htmlspecialchars($error_msg, ENT_QUOTES, 'UTF-8'); ?></div><?php else: ?><div class="qr-box"><div id="qrcode"></div></div><div class="countdown">支付剩余时间：<b id="timer">--:--</b></div><div class="meta">订单号：<?php echo htmlspecialchars((string)$order['trade_no'], ENT_QUOTES, 'UTF-8'); ?><br>门店号：<?php echo htmlspecialchars((string)($channel['store_sn'] ?? ''), ENT_QUOTES, 'UTF-8'); ?><br>终端号：<?php echo htmlspecialchars((string)($channel['terminal_sn'] ?? ''), ENT_QUOTES, 'UTF-8'); ?></div><div class="hint">请使用支付宝或微信扫描二维码完成支付<br>支付完成后页面会自动跳转</div><?php endif; ?></main><script src="<?php echo htmlspecialchars($cdnpublic, ENT_QUOTES, 'UTF-8'); ?>jquery/1.12.4/jquery.min.js"></script><script src="<?php echo htmlspecialchars($cdnpublic, ENT_QUOTES, 'UTF-8'); ?>jquery.qrcode/1.0/jquery.qrcode.min.js"></script><?php if ($error_msg === ''): ?><script>(function(){var code=<?php echo $codeJson; ?>,remain=<?php echo (int)$paytime; ?>,timer=document.getElementById('timer');if(/^data:image\//i.test(code)){var img=document.createElement('img');img.src=code;img.alt='支付二维码';document.getElementById('qrcode').appendChild(img)}else if(window.jQuery&&jQuery.fn.qrcode){jQuery('#qrcode').qrcode({text:code,width:230,height:230,typeNumber:-1})}function tick(){if(remain<=0){timer.textContent='00:00';return}var m=Math.floor(remain/60),s=remain%60;timer.textContent=(m<10?'0':'')+m+':'+(s<10?'0':'')+s;remain--}tick();setInterval(tick,1000);function check(){jQuery.getJSON('/getshop.php',{trade_no:<?php echo json_encode((string)$order['trade_no']); ?>},function(d){if(d&&d.code===1&&d.backurl){location.href=d.backurl}else if(remain>0)setTimeout(check,2000)}).fail(function(){if(remain>0)setTimeout(check,3000)})}setTimeout(check,1800)})();</script><?php endif; ?></body></html>
